CREATE FUNCTION public.network_regional_service_areas() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('workspace_id',p.workspace_id,'areas',coalesce((SELECT jsonb_agg(jsonb_build_object('state',a->>'state','countyEquivalent',a->>'countyEquivalent','countyType',a->>'countyType','locality',a->>'locality','postalCode',a->>'postalCode','region',a->>'region','evidence','generalized')) FROM jsonb_array_elements(coalesce(p.regional_service_areas->'areas','[]')) a),'[]'))),'[]') FROM public.provider_network_profiles p WHERE auth.uid() IS NOT NULL AND EXISTS(SELECT 1 FROM public.list_network_providers() v WHERE v.workspace_id=p.workspace_id) $$;
REVOKE ALL ON FUNCTION public.network_regional_service_areas() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.network_regional_service_areas() TO authenticated;
CREATE FUNCTION public.regional_configuration_history() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.platform_master_admin WHERE user_id=auth.uid()) THEN RAISE EXCEPTION 'Master Admin required'; END IF; RETURN (SELECT coalesce(jsonb_agg(r),'[]') FROM (SELECT event_type,result,details,created_at FROM public.account_security_audit WHERE event_type='regional_configuration_changed' ORDER BY created_at DESC LIMIT 50) r); END $$;
REVOKE ALL ON FUNCTION public.regional_configuration_history() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.regional_configuration_history() TO authenticated;